{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Public IP assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration explicitly assigns public IP addresses to instances, increasing their exposure to internet-based threats."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "IMDSv1 is permitted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not require IMDS session tokens, allowing instances to use IMDSv1 and increasing the risk of metadata credential theft through SSRF."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Root EBS volume encryption not enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly encrypt its root EBS volume, potentially leaving instance data unencrypted at rest."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n\n  user_data = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n}\n",
  "fix_summary": "Disabled automatic public IP assignment, required IMDSv2 session tokens, and enabled encryption for the instance root EBS volume."
}
